import type { ReactNode } from 'react'

type Props = {
  children?: ReactNode
  className?: string
}

export function HeroBanner({ children, className }: Props) {
  return (
    <div
      className={`relative w-full overflow-hidden ${className ?? ''}`}
      style={{ height: 'var(--hero-height)', background: 'linear-gradient(135deg, hsl(var(--gradient-from)), hsl(var(--gradient-to)))' }}
    >
      {/* Geometric diamond pattern overlay */}
      <svg
        className="absolute inset-0 w-full h-full opacity-10"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        <defs>
          <pattern id="diamonds" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
            <polygon points="20,2 38,20 20,38 2,20" fill="none" stroke="currentColor" strokeWidth="1" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#diamonds)" />
      </svg>
      <div className="relative z-10 h-full">{children}</div>
    </div>
  )
}
